package com.ruoyi.framework.audit;
import java.util.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.math.BigDecimal;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import com.ruoyi.common.utils.SecurityUtils;import com.ruoyi.common.exception.ServiceException;import com.ruoyi.metal.security.FactoryScope;
@Service public class LogQueryService {
 private final JdbcTemplate jdbc;private final FactoryScope scope;public LogQueryService(JdbcTemplate j,FactoryScope s){jdbc=j;scope=s;}
 public void admin(){scope.adminOnly();}private record Query(String table,String id,String time,String where,List<Object> args){}
 private Query query(String kind,Map<String,String> p){boolean runtime=kind.equals("runtime"),login=kind.equals("login");if(runtime||login)admin();String table=runtime?"sys_runtime_log":login?"sys_logininfor":"sys_oper_log",id=runtime?"id":login?"info_id":"oper_id",time=runtime?"event_time":login?"login_time":"oper_time";LocalDateTime now=LocalDateTime.now(ZoneId.of("Asia/Shanghai")),start=parse(p.get("startTime"),now.minusDays(runtime?1:7)),end=parse(p.get("endTime"),now);if(!start.isBefore(end)||Duration.between(start,end).compareTo(Duration.ofDays(runtime?7:31))>0)throw new ServiceException("查询时间范围无效或超过上限");StringBuilder where=new StringBuilder(" WHERE "+time+">=? AND "+time+"<=?");List<Object> args=new ArrayList<>(List.of(start,end));if(!runtime&&!login){Long factory=scope.currentFactory();if(factory!=null){where.append(" AND business_factory_id=? AND NOT EXISTS(SELECT 1 FROM audit_scope s WHERE s.oper_id=sys_oper_log.oper_id AND s.factory_id<>?)");args.add(factory);args.add(factory);}else if(p.get("factoryId")!=null&&!p.get("factoryId").isBlank()){where.append(" AND business_factory_id=?");args.add(Long.valueOf(p.get("factoryId")));}}
 Map<String,String> fields=runtime?Map.of("level","level","component","component","traceId","trace_id"):login?Map.of("actor","user_name","status","status","traceId","trace_id"):Map.of("actor","oper_name","module","title","resultCode","result_code","businessCode","business_code","traceId","trace_id","action","action_code");for(var f:fields.entrySet()){String value=p.get(f.getKey());if(value==null||value.isBlank())continue;if(f.getKey().equals("actor"))value=AuditRedactor.text(value);if(value.length()>160)throw new ServiceException("查询条件过长");where.append(" AND "+f.getValue()+(f.getKey().equals("traceId")?"=?":" LIKE ?"));args.add(f.getKey().equals("traceId")?value:"%"+value+"%");}return new Query(table,id,time,where.toString(),args);}
 private LocalDateTime parse(String s,LocalDateTime fallback){try{return s==null||s.isBlank()?fallback:LocalDateTime.parse(s.replace(' ','T'));}catch(Exception e){throw new ServiceException("时间格式错误");}}
 private Map<String,Object> clean(Map<String,Object> r){Map<String,Object> out=new LinkedHashMap<>();r.forEach((k,v)->{StringBuilder key=new StringBuilder();boolean upper=false;for(char c:k.toCharArray()){if(c=='_'){upper=true;continue;}key.append(upper?Character.toUpperCase(c):c);upper=false;}Object x=v;if(v instanceof java.sql.Timestamp t)x=t.toLocalDateTime().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));else if(v instanceof Long||v instanceof BigDecimal)x=v.toString();out.put(key.toString(),x);});return (Map<String,Object>)AuditRedactor.redact(out);}
 public Map<String,Object> list(String kind,Map<String,String> p,boolean export){Query q=query(kind,p);int page=num(p.get("pageNum"),1),size=num(p.get("pageSize"),16);if(page<1||size<1||size>100)throw new ServiceException("分页参数无效");long count=jdbc.queryForObject("SELECT COUNT(*) FROM "+q.table+q.where,Long.class,q.args.toArray());if(export&&count>10000)throw new ServiceException("导出超过10000条，请缩小条件");List<Object> args=new ArrayList<>(q.args);args.add(export?10000:size);args.add(export?0:(page-1)*size);String columns=kind.equals("operation")?"oper_id id,oper_time,factory_name,actor_name,oper_name,title,action_code,result_code,business_code,cost_time,trace_id,status":"*";var rows=jdbc.queryForList("SELECT "+columns+" FROM "+q.table+q.where+" ORDER BY "+q.time+" DESC,"+q.id+" DESC LIMIT ? OFFSET ?",args.toArray()).stream().map(this::clean).toList();return Map.of("code",200,"rows",rows,"total",count);}
 private int num(String x,int fallback){try{return x==null?fallback:Integer.parseInt(x);}catch(Exception e){throw new ServiceException("分页参数错误");}}
 public Map<String,Object> detail(String kind,Long id){if(kind.equals("runtime"))admin();String table=kind.equals("runtime")?"sys_runtime_log":"sys_oper_log",pk=kind.equals("runtime")?"id":"oper_id";var rows=jdbc.queryForList("SELECT * FROM "+table+" WHERE "+pk+"=?",id);if(rows.isEmpty())throw new ServiceException("日志不存在");var row=rows.get(0);if(!kind.equals("runtime")){Long factory=scope.currentFactory();if(factory!=null&&(row.get("business_factory_id")==null||!factory.equals(((Number)row.get("business_factory_id")).longValue())||jdbc.queryForObject("SELECT COUNT(*) FROM audit_scope WHERE oper_id=? AND factory_id<>?",Integer.class,id,factory)>0))throw new ServiceException("无权访问该日志",403);}return clean(row);}
 public Map<String,Object> config(){admin();var r=clean(jdbc.queryForMap("SELECT * FROM audit_log_config WHERE id=1"));r.put("pending",jdbc.queryForObject("SELECT COUNT(*) FROM audit_outbox WHERE status='PENDING'",Long.class).toString());r.put("failedDeliveries",jdbc.queryForObject("SELECT COUNT(*) FROM audit_outbox WHERE status='PENDING' AND attempts>0",Long.class).toString());r.put("runtimeCollected",jdbc.queryForObject("SELECT COUNT(*) FROM sys_runtime_log",Long.class).toString());var oldest=jdbc.queryForMap("SELECT MIN(create_time) oldestPendingTime,COALESCE(TIMESTAMPDIFF(SECOND,MIN(create_time),NOW()),0) oldestPendingSeconds FROM audit_outbox WHERE status='PENDING'");r.putAll(clean(oldest));r.put("deliveredLastMinute",jdbc.queryForObject("SELECT COUNT(*) FROM audit_outbox WHERE status='DELIVERED' AND delivered_time>=DATE_SUB(NOW(),INTERVAL 1 MINUTE)",Long.class).toString());r.put("cleanupProgress",jdbc.queryForList("SELECT business_date,status,stage,operation_count,login_count,runtime_count,outbox_count FROM audit_cleanup_history WHERE status<>'SUCCESS' ORDER BY business_date LIMIT 1").stream().map(this::clean).toList());r.put("diskFreeBytes",java.nio.file.Path.of("logs").toFile().getUsableSpace()+"");return r;}
 @org.springframework.transaction.annotation.Transactional public void config(Map<String,Object> p){admin();String[] keys={"operationDays","loginDays","runtimeDays","fileDays","archiveDays","slowRequestMs","slowSqlMs"};String[] columns={"operation_days","login_days","runtime_days","file_days","archive_days","slow_request_ms","slow_sql_ms"};var old=jdbc.queryForMap("SELECT * FROM audit_log_config WHERE id=1 FOR UPDATE");List<Object> args=new ArrayList<>();StringJoiner set=new StringJoiner(",");for(int i=0;i<keys.length;i++){int v=p.get(keys[i])==null?((Number)old.get(columns[i])).intValue():Integer.parseInt(p.get(keys[i]).toString());if(v<1||v>(i>=5?600000:3650))throw new ServiceException("配置超出允许范围");set.add(columns[i]+"=?");args.add(v);}set.add("cleanup_enabled=?");args.add(Boolean.TRUE.equals(p.get("cleanupEnabled")));args.add(p.get("version"));if(jdbc.update("UPDATE audit_log_config SET "+set+",version=version+1 WHERE id=1 AND version=?",args.toArray())!=1)throw new ServiceException("配置已修改，请刷新后重试");}
 public List<Map<String,Object>> cleanupHistory(){admin();return jdbc.queryForList("SELECT * FROM audit_cleanup_history ORDER BY id DESC LIMIT 100").stream().map(this::clean).toList();}
 public Map<String,Object> trace(String trace){admin();if(!trace.matches("[a-f0-9]{32}"))throw new ServiceException("追踪ID格式错误");return Map.of("operations",jdbc.queryForList("SELECT oper_id id,oper_time,title,result_code FROM sys_oper_log WHERE trace_id=? ORDER BY oper_id",trace).stream().map(this::clean).toList(),"runtime",jdbc.queryForList("SELECT id,event_time,level,summary FROM sys_runtime_log WHERE trace_id=? ORDER BY id",trace).stream().map(this::clean).toList());}
}
